 async function deleteMasterRecord(kind:string,r:any){
  if(!r?.id||!districtId)return;const table=uploadConfig[kind]?.table;if(!table)return;
  if(!confirm("Permanently delete this "+kind+" record from the selected district? This cannot be undone."))return;
  setBusy(true);try{
   if(kind==="Staff Data"){
    const [a,p,v]=await Promise.all([supabase.from("staff_assignments").select("id",{count:"exact",head:true}).eq("district_id",districtId).eq("staff_id",r.id),supabase.from("training_participants").select("id",{count:"exact",head:true}).eq("district_id",districtId).eq("staff_id",r.id),supabase.from("reserve_staff").select("id",{count:"exact",head:true}).eq("district_id",districtId).eq("staff_id",r.id)]);
    if(a.error||p.error||v.error)throw a.error||p.error||v.error;if((a.count||0)+(p.count||0)+(v.count||0)>0)throw new Error("This staff member has duty, reserve or training history. Mark Availability = N instead of deleting, so history is preserved.");
   }
   if(kind==="Training Venues"){const q=await supabase.from("training_batches").select("id",{count:"exact",head:true}).eq("district_id",districtId).eq("venue_id",r.id);if(q.error)throw q.error;if((q.count||0)>0)throw new Error("This venue is used by saved training batches. Keep it and mark Availability = No.");}
   if(kind==="Master Trainers"){const q=await supabase.from("training_batches").select("id,batch_data").eq("district_id",districtId);if(q.error)throw q.error;if((q.data||[]).some((b:any)=>b.batch_data?.master_trainer_id===r.id))throw new Error("This trainer is referenced by a training batch. Keep the record to preserve training history.");}
   if(kind==="Training Plans"){const q=await supabase.from("training_batches").select("id",{count:"exact",head:true}).eq("district_id",districtId).eq("plan_id",r.id);if(q.error)throw q.error;if((q.count||0)>0)throw new Error("This plan has scheduled batches. It cannot be deleted until its training history is archived.");}
   const {error}=await (supabase as any).from(table).delete().eq("id",r.id).eq("district_id",districtId);if(error)throw error;
   await loadDistrictData();const refreshed=await fetchAllDistrictRows(table,"*",districtId);if(refreshed.error)throw refreshed.error;setUploadRecords(refreshed.data||[]);setNotice(kind+" record deleted from the selected district.");
  }catch(e){setNotice("Delete blocked: "+(e instanceof Error?e.message:String(e)));}finally{setBusy(false);}
 }
 async function createDistrict(){
  const name=newDistrictName.trim(),code=newDistrictCode.trim().toUpperCase().replace(/[^A-Z0-9_-]/g,"");
  if(!name||!code){setNotice("Enter both the new district name and a short unique code.");return;}
  setBusy(true);setNotice("Creating district workspace…");
  try{const {data,error}=await supabase.from("districts").insert({name,code,is_active:true}).select("id,name,code").single();if(error)throw error;setDistricts(prev=>[...prev,data].sort((a,b)=>a.name.localeCompare(b.name)));setDistrictId(data.id);setNewDistrictName("");setNewDistrictCode("");setNotice("District workspace created. Upload its DATA, Staff, Trainers, Venues, Rules and Settings separately.");}
  catch(e){setNotice("Could not create district: "+(e instanceof Error?e.message:String(e)));}
  finally{setBusy(false);}
 }
